// WF-03 | Stage 2 - Context & Intent Extraction
const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

const reqOrgId = (typeof body.organization_id === 'string' ? body.organization_id.trim() : '');
const orgId = UUID_RE.test(reqOrgId) ? reqOrgId : '11111111-1111-4111-8111-111111111111';

const rawCorr = headers['x-correlation-id'] || body.correlation_id || '';
const correlationId = UUID_RE.test(rawCorr) ? rawCorr : uuid();

const apiKey = headers['x-api-key'] || headers['authorization'] || '';
const expectedKey = 'change-this-core-api-key';
const apiKeyValid = Boolean(apiKey && (apiKey === expectedKey || apiKey === `Bearer ${expectedKey}`));

let phone = String(body.phone || body.customer_phone || '').trim().replace(/[^\d+]/g, '');
if (/^0\d{9}$/.test(phone)) phone = '+84' + phone.slice(1);

const leadId = UUID_RE.test(body.lead_id) ? body.lead_id : '00000000-0000-0000-0000-000000000000';
const fullName = String(body.full_name || body.customer_name || '').trim();
const sourceChannel = String(body.source_channel || body.channel || 'voice_call').trim();

const lastInteraction = body.last_interaction || {};
const intent = String(lastInteraction.intent || body.intent || 'general_inquiry').trim();
const sentiment = String(lastInteraction.sentiment || body.sentiment || 'neutral').trim();
const summary = String(lastInteraction.summary || body.summary || body.transcript || 'Khách quan tâm dịch vụ AI Sales').trim();

const errors = [];
if (!apiKeyValid) errors.push({ field: 'auth', message: 'X-API-Key không hợp lệ hoặc thiếu.' });
if (!phone && leadId === '00000000-0000-0000-0000-000000000000') {
  errors.push({ field: 'lead', message: 'Yêu cầu cung cấp lead_id hoặc phone để định danh khách hàng.' });
}

return [{
  json: {
    valid: errors.length === 0,
    apiKeyValid,
    errors,
    organization_id: orgId,
    correlation_id: correlationId,
    lead_id: leadId,
    phone: phone || '+84987654321',
    full_name: fullName,
    source_channel: sourceChannel,
    last_interaction: {
      intent,
      sentiment,
      summary
    },
    received_at: new Date().toISOString()
  }
}];

