// WF-03 | Stage 6 - Context Analyzer & Next-Best-Action Engine
const req = $('02 Context & Intent Extraction').first().json;
const lead = $('04 Fetch Lead & 360 Context').first()?.json || {};
const runRecord = $('05 Create Workflow Run').first().json;

const intent = req.last_interaction.intent;
const sentiment = req.last_interaction.sentiment;
const summary = req.last_interaction.summary;
const customerName = (lead.first_name && lead.first_name !== 'Quý khách') ? `${lead.first_name} ${lead.last_name || ''}`.trim() : (req.full_name || 'Quý khách');

let chosenTool = 'tool_nurture_lead';
let targetWorkflow = 'WF-13';
let confidence = 0.85;
let reason = 'Duy trì chăm sóc và theo dõi tiềm năng.';
let scoreDelta = 10;
let nextStatus = 'contacted';
let recommendedPackage = 'Starter';
let quoteAmount = 2000000;

if (intent === 'request_proposal' || intent === 'pricing' || /báo giá|gói pro|chi phí/i.test(summary)) {
  chosenTool = 'tool_generate_quote';
  targetWorkflow = 'WF-14';
  recommendedPackage = /pro/i.test(summary) ? 'Pro' : 'Starter';
  quoteAmount = recommendedPackage === 'Pro' ? 5000000 : 2000000;
  confidence = 0.96;
  reason = `Khách hàng ${customerName} yêu cầu báo giá (${recommendedPackage}) với mức độ quan tâm cao.`;
  scoreDelta = 25;
  nextStatus = 'proposal_sent';
} else if (intent === 'schedule_meeting' || /demo|hẹn|gặp tư vấn|lịch/i.test(summary)) {
  chosenTool = 'tool_schedule_meeting';
  targetWorkflow = 'WF-17';
  confidence = 0.92;
  reason = `Khách hàng ${customerName} muốn đặt lịch demo chi tiết hệ thống AI Sales.`;
  scoreDelta = 20;
  nextStatus = 'meeting_scheduled';
} else if (intent === 'speak_to_human' || intent === 'complaint' || sentiment === 'negative' || /khiếu nại|lỗi/i.test(summary)) {
  chosenTool = 'tool_escalate_support';
  targetWorkflow = 'WF-02';
  confidence = 0.94;
  reason = `Phát hiện rủi ro hoặc yêu cầu hỗ trợ gấp từ ${customerName}, cần chuyển chuyên viên xử lý.`;
  scoreDelta = -5;
  nextStatus = 'escalated';
} else if (intent === 'budget_constraint' || /ngân sách|để sau|chưa có nhu cầu/i.test(summary)) {
  chosenTool = 'tool_followup_email';
  targetWorkflow = 'WF-21';
  confidence = 0.88;
  reason = `Khách hàng chưa có ngân sách, kích hoạt chuỗi email bám đuổi định kỳ nuôi dưỡng.`;
  scoreDelta = 5;
  nextStatus = 'nurturing';
}

return [{
  json: {
    workflow_run_id: runRecord.id,
    correlation_id: req.correlation_id,
    organization_id: lead.organization_id || req.organization_id,
    lead_id: lead.id,
    customer_name: customerName,
    customer_phone: lead.phone || req.phone,
    customer_email: lead.email,
    company_name: lead.company_name || 'Doanh nghiệp',
    decision: {
      chosen_tool: chosenTool,
      target_workflow: targetWorkflow,
      confidence,
      reason,
      action_summary: `AI Orchestrator kích hoạt ${chosenTool} điều phối sang ${targetWorkflow}.`
    },
    lifecycle_update: {
      score_delta: scoreDelta,
      next_status: nextStatus
    },
    tool_parameters: {
      recommended_package: recommendedPackage,
      quote_amount: quoteAmount,
      contact_name: customerName,
      phone: lead.phone || req.phone
    }
  }
}];

// WF-03 | Stage 7 - Dynamic Tool Dispatcher
const item = $input.first().json;
const tool = item.decision.chosen_tool;

let actionResult = {};

if (tool === 'tool_generate_quote') {
  actionResult = {
    status: 'dispatched',
    action: 'quote_generation',
    quote_id: 'QT-' + Math.random().toString(16).slice(2, 8).toUpperCase(),
    package: item.tool_parameters.recommended_package,
    amount: item.tool_parameters.quote_amount,
    valid_until: new Date(Date.now() + 14 * 24 * 3600 * 1000).toISOString().slice(0, 10),
    message: `Đã sinh báo giá ${item.tool_parameters.recommended_package} (${item.tool_parameters.quote_amount.toLocaleString()} VND) gửi khách hàng.`
  };
} else if (tool === 'tool_schedule_meeting') {
  actionResult = {
    status: 'dispatched',
    action: 'calendar_booking',
    meeting_link: 'https://meet.google.com/sales-demo-' + Math.random().toString(16).slice(2, 6),
    scheduled_time: new Date(Date.now() + 2 * 24 * 3600 * 1000).toISOString(),
    message: `Đã tạo lời mời demo qua Google Calendar.`
  };
} else if (tool === 'tool_escalate_support') {
  actionResult = {
    status: 'dispatched',
    action: 'hotline_escalation',
    ticket_id: 'TCK-' + Math.random().toString(16).slice(2, 8).toUpperCase(),
    priority: 'urgent',
    hotline: '+842471088888',
    message: `Đã chuyển tiếp cuộc gọi khẩn cấp tới chuyên viên hỗ trợ.`
  };
} else if (tool === 'tool_followup_email') {
  actionResult = {
    status: 'dispatched',
    action: 'drip_campaign_enrolled',
    sequence_name: 'budget_friendly_nurturing_v1',
    next_email_in_days: 3,
    message: `Đã đưa vào chuỗi email chăm sóc bám đuổi tự động.`
  };
} else {
  actionResult = {
    status: 'dispatched',
    action: 'nurture_tagging',
    tag: 'ai_warm_lead',
    message: `Đã cập nhật tag nuôi dưỡng khách hàng tiềm năng.`
  };
}

return [{
  json: {
    ...item,
    action_result: actionResult
  }
}];

