// WF-03 | Stage 12 - Success Log
const data = $('07 Dynamic Tool Dispatcher').first().json;

return [{
  json: {
    status: 'success',
    data: {
      lead_id: data.lead_id,
      customer_name: data.customer_name,
      customer_phone: data.customer_phone,
      decision: data.decision,
      action_result: data.action_result,
      workflow_run_id: data.workflow_run_id,
      correlation_id: data.correlation_id
    }
  }
}];

// WF-03 | Stage 15 - Error Handle
const err = $input.first().json?.execution?.error || {};
const failedNode = $input.first().json?.execution?.lastNodeExecuted || 'unknown';

let workflowRunId = null;
try { workflowRunId = $('05 Create Workflow Run').first()?.json?.id || null; } catch (e) {}

return [{
  json: {
    workflowRunId,
    error: { message: err.message || 'Orchestration execution failed', failedNode, timestamp: new Date().toISOString() }
  }
}];
